if (!page_id && !url) throw new Error('job-resume requires page_id or url');
return { json: { url: url, page_id: page_id, resume_by: page_id ? 'page_id' : 'url' } };

const ingest = $('Pack Resume').first().json;
const raw = String($json.stdout || $json.data || '').trim();
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('load_secret_ids.py returned no JSON');
const ids = JSON.parse(match[0]);
if (!ids.applications_db_id || !ids.style_learnings_page_id || !ids.anthropic_api_key) {
  throw new Error('Resume Secret IDs missing required fields from secrets/notion_ids.json');
}
return { json: Object.assign({}, ingest, ids) };

const prev = $('Parse Write Full').first().json;
return { json: {
  status: 'ready_to_apply',
  company: prev.company || '',
  job_title: prev.job_title || '',
  cv_path: prev.cv_path || '',
  letter_path: prev.letter_path || '',
  usage_triage: prev.usage_triage || {},
  usage_phase1: prev.usage_phase1 || {},
  usage_phase2: prev.usage_phase2 || {}
} };

const page = $json;
const page_id = String(page.id || page.pageId || '').replace(/-/g, '').toLowerCase();
const url = $('Secret IDs').first().json.url || '';
return { json: {
  status: 'duplicate',
  page_id: page_id,
  url: url,
  message: 'Already filed. Click Continue Phase 2 to generate from Candidate Answers.'
} };
